import { test, expect, Page } from '@playwright/test';

test.describe('Search Filter - No Results Message', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display "No results" message when search returns no matches', async () => {
    // Find and interact with the search input
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('nonexistentitem12345');

    // Wait for search results to update
    await page.waitForTimeout(500);

    // Verify "No results" message is displayed
    const noResultsMessage = page.getByText(/no results/i);
    await expect(noResultsMessage).toBeVisible();
  });

  test('should display "No results" message with special characters in search', async () => {
    // Find and interact with the search input
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('!@#$%^&*()');

    // Wait for search results to update
    await page.waitForTimeout(500);

    // Verify "No results" message is displayed
    const noResultsMessage = page.getByText(/no results/i);
    await expect(noResultsMessage).toBeVisible();
  });

  test('should hide "No results" message when search returns matches', async () => {
    // First perform a search that returns no results
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('nonexistentitem12345');
    await page.waitForTimeout(500);

    // Verify "No results" message is displayed
    let noResultsMessage = page.getByText(/no results/i);
    await expect(noResultsMessage).toBeVisible();

    // Clear search and enter a valid search term
    await searchInput.clear();
    await searchInput.fill('test');
    await page.waitForTimeout(500);

    // Verify "No results" message is no longer visible
    noResultsMessage = page.getByText(/no results/i);
    await expect(noResultsMessage).not.toBeVisible();
  });

  test('should display "No results" message when filtering with no matching criteria', async () => {
    // Find filter button or dropdown
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    // Select a filter option that returns no results
    const filterOption = page.getByRole('option', { name: /archived/i });
    await filterOption.click();

    // Wait for results to update
    await page.waitForTimeout(500);

    // Verify "No results" message is displayed
    const noResultsMessage = page.getByText(/no results/i);
    await expect(noResultsMessage).toBeVisible();
  });

  test('should display appropriate "No results" message with empty search after clearing', async () => {
    // Perform initial search
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('test');
    await page.waitForTimeout(500);

    // Clear the search input
    await searchInput.clear();
    await page.waitForTimeout(500);

    // Verify "No results" message appears when search is empty
    const noResultsMessage = page.getByText(/no results/i);
    await expect(noResultsMessage).toBeVisible();
  });

  test('should maintain "No results" message state during rapid searches', async () => {
    const searchInput = page.getByRole('searchbox');

    // Perform rapid searches
    await searchInput.fill('xyz');
    await page.waitForTimeout(300);

    await searchInput.clear();
    await searchInput.fill('abc');
    await page.waitForTimeout(300);

    await searchInput.clear();
    await searchInput.fill('nonexistent');
    await page.waitForTimeout(500);

    // Verify "No results" message is displayed
    const noResultsMessage = page.getByText(/no results/i);
    await expect(noResultsMessage).toBeVisible();
  });
});
